# name: frac_participants_prefer_fewer_switches
# description: Fraction of participants who, on pairs differing in switch count, choose the sequence with FEWER switches more than half the time; observed above null_mean means some people hold a reversed (streaky-is-random) preference that the model's shared-sign sensitivity cannot represent.
def test_statistic(df):
    def sw(s):
        return sum(x != y for x, y in zip(s, s[1:]))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    SW = {s: sw(s) for s in u}
    ka = df["sequence_a"].map(SW).values; kb = df["sequence_b"].map(SW).values
    m = ka != kb
    if m.sum() == 0:
        return 0.0
    y = df["chose_left"].values
    fewer = np.where(ka < kb, y, 1 - y).astype(float)
    s = pd.Series(fewer[m]).groupby(df["participant_id"].values[m]).mean()
    return float((s > 0.5).mean())

# name: participant_side_bias_variance
# description: Variance across participants of their rate of choosing the LEFT sequence; observed above null_mean means people have idiosyncratic side (left/right) response biases the model lacks.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().var())

# name: balance_pref_equal_switches
# description: Among pairs with equal switch counts but different |#H - #T|, the rate of choosing the more balanced sequence; observed above null_mean means people reward H/T balance more than the model's biased-coin generator implies (below: less).
def test_statistic(df):
    def sw(s):
        return sum(x != y for x, y in zip(s, s[1:]))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    SW = {s: sw(s) for s in u}
    ka = df["sequence_a"].map(SW).values; kb = df["sequence_b"].map(SW).values
    L = df["sequence_a"].str.len().values
    ia = np.abs(2 * df["sequence_a"].str.count("H").values - L)
    ib = np.abs(2 * df["sequence_b"].str.count("H").values - L)
    m = (ka == kb) & (ia != ib)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].values
    return float(np.mean(np.where(ia < ib, y, 1 - y)[m]))

# name: longest_run_pref_equal_switches
# description: Among pairs with equal switch counts but different longest runs, the rate of choosing the sequence with the shorter longest run as more random; observed above null_mean means people penalise long runs more than the model (which sees only switch counts, bias and periodicity).
def test_statistic(df):
    def lr(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    def sw(s):
        return sum(x != y for x, y in zip(s, s[1:]))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    LR = {s: lr(s) for s in u}; SW = {s: sw(s) for s in u}
    la = df["sequence_a"].map(LR).values; lb = df["sequence_b"].map(LR).values
    ka = df["sequence_a"].map(SW).values; kb = df["sequence_b"].map(SW).values
    m = (ka == kb) & (la != lb)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].values[m]
    a_short = (la < lb)[m]
    return float(np.mean(np.where(a_short, y, 1 - y)))
